# CSS
Path('frontend/src/brand.css').write_text('''/* DGD 2.0 – Markenprofile */\n.brand-profile{max-width:1280px;margin:0 auto;padding:34px 28px 100px}.brand-profile-toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:34px;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.12em}.brand-profile-toolbar button{display:flex;align-items:center;gap:8px;border:1px solid var(--line);background:var(--surface);color:var(--text);padding:11px 15px;border-radius:12px;cursor:pointer;text-transform:none;letter-spacing:0}.brand-profile-hero{display:grid;grid-template-columns:260px 1fr;gap:54px;align-items:center;padding:46px;border:1px solid var(--line);border-radius:32px;background:linear-gradient(145deg,var(--surface),var(--surface2))}.brand-monogram{width:230px;height:230px;border-radius:50%;display:grid;place-items:center;font-family:'Playfair Display';font-size:76px;color:var(--gold);border:1px solid color-mix(in srgb,var(--gold) 50%,var(--line));background:radial-gradient(circle,color-mix(in srgb,var(--gold) 16%,transparent),transparent 65%)}.brand-profile-hero h1{font-family:'Playfair Display';font-size:clamp(54px,8vw,96px);line-height:.95;margin:10px 0 22px}.brand-profile-meta{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:23px}.brand-profile-meta span{display:flex;align-items:center;gap:7px;padding:8px 11px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:12px}.brand-profile-meta .verified{color:#3aa879}.brand-profile-hero p{max-width:780px;color:var(--muted);font-size:17px;line-height:1.8}.brand-profile-hero a{display:inline-flex;align-items:center;gap:7px;color:var(--gold);text-decoration:none;margin-top:8px}.brand-profile-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:28px 0 70px}.brand-profile-stats article{padding:24px;border:1px solid var(--line);border-radius:20px;background:var(--surface)}.brand-profile-stats strong{display:block;font-family:'Playfair Display';font-size:38px;color:var(--gold)}.brand-profile-stats span{color:var(--muted);font-size:12px}.brand-profile-catalog{border-top:1px solid var(--line);padding-top:64px}.brand-catalog-tools{display:flex;gap:10px;align-items:center}.brand-catalog-tools>div{display:flex;align-items:center;gap:8px;border:1px solid var(--line);background:var(--surface);padding:0 12px;border-radius:12px}.brand-catalog-tools input,.brand-catalog-tools select{border:0;background:transparent;color:var(--text);padding:11px;outline:0}.brand-catalog-tools select{border:1px solid var(--line);background:var(--surface);border-radius:12px}.detail-brand-link{display:inline-flex;align-items:center;gap:5px;border:0;background:transparent;padding:0;cursor:pointer;color:var(--gold)}@media(max-width:800px){.brand-profile-hero{grid-template-columns:1fr;padding:30px}.brand-monogram{width:170px;height:170px;font-size:56px}.brand-profile-stats{grid-template-columns:1fr}.brand-profile-catalog .section-head{align-items:flex-start}.brand-catalog-tools{width:100%;flex-direction:column;align-items:stretch}.brand-catalog-tools>div{width:100%}}@media(max-width:560px){.brand-profile{padding:24px 16px 70px}.brand-profile-toolbar>span{display:none}.brand-profile-hero{padding:23px;border-radius:24px}.brand-profile-hero h1{font-size:52px}.brand-profile-hero p{font-size:15px}}\n''',encoding='utf-8')

